const invitationHasSeatCapacity = `-- name: InvitationHasSeatCapacity :one
SELECT EXISTS(
    SELECT 1
    FROM workspaces w
    JOIN roles r ON r.id = $1
    WHERE w.id = $2
      AND w.kind = 'business'
      AND w.status = 'active'
      AND (r.workspace_id = w.id OR (r.is_system AND r.workspace_id IS NULL))
      AND (
          (r.code = 'accountant' AND (
              SELECT count(*)
              FROM memberships m
              JOIN roles mr ON mr.id = m.role_id
              WHERE m.workspace_id = w.id AND m.status = 'active' AND NOT m.is_owner AND mr.code = 'accountant'
          ) < w.accountant_seat_limit)
          OR
          (r.code <> 'accountant' AND (
              SELECT count(*)
              FROM memberships m
              JOIN roles mr ON mr.id = m.role_id
              WHERE m.workspace_id = w.id AND m.status = 'active' AND NOT m.is_owner AND mr.code <> 'accountant'
          ) < w.staff_seat_limit)
      )
)
`

type InvitationHasSeatCapacityParams struct {
	RoleID      int64 `json:"role_id"`
	WorkspaceID int64 `json:"workspace_id"`
}

func (q *Queries) InvitationHasSeatCapacity(ctx context.Context, arg InvitationHasSeatCapacityParams) (bool, error) {
	row := q.db.QueryRow(ctx, invitationHasSeatCapacity, arg.RoleID, arg.WorkspaceID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

