const listActiveUserSessions = `-- name: ListActiveUserSessions :many
SELECT id, user_id, family_id, refresh_digest, previous_session_id, replaced_by_session_id, session_kind, device_label, user_agent_summary, ip_prefix, issued_at, expires_at, last_seen_at, rotated_at, revoked_at, revocation_reason, created_at, csrf_digest FROM sessions
WHERE user_id = $1 AND revoked_at IS NULL AND expires_at > now()
ORDER BY last_seen_at DESC, id DESC
`

func (q *Queries) ListActiveUserSessions(ctx context.Context, userID int64) ([]Session, error) {
	rows, err := q.db.Query(ctx, listActiveUserSessions, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Session{}
	for rows.Next() {
		var i Session
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.FamilyID,
			&i.RefreshDigest,
			&i.PreviousSessionID,
			&i.ReplacedBySessionID,
			&i.SessionKind,
			&i.DeviceLabel,
			&i.UserAgentSummary,
			&i.IpPrefix,
			&i.IssuedAt,
			&i.ExpiresAt,
			&i.LastSeenAt,
			&i.RotatedAt,
			&i.RevokedAt,
			&i.RevocationReason,
			&i.CreatedAt,
			&i.CsrfDigest,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recordAuthRateLimitFailure = `-- name: RecordAuthRateLimitFailure :one
INSERT INTO auth_rate_limits (subject_digest, action, window_started_at, attempt_count, blocked_until)
VALUES ($1, $2, now(), 1, NULL)
ON CONFLICT (subject_digest, action) DO UPDATE SET
    window_started_at = CASE
        WHEN auth_rate_limits.window_started_at < now() - $3::integer * interval '1 second' THEN now()
        ELSE auth_rate_limits.window_started_at
    END,
    attempt_count = CASE
        WHEN auth_rate_limits.window_started_at < now() - $3::integer * interval '1 second' THEN 1
        ELSE auth_rate_limits.attempt_count + 1
    END,
    blocked_until = CASE
        WHEN auth_rate_limits.window_started_at >= now() - $3::integer * interval '1 second'
             AND auth_rate_limits.attempt_count + 1 >= $4::integer
        THEN now() + $5::integer * interval '1 second'
        ELSE auth_rate_limits.blocked_until
    END,
    updated_at = now()
RETURNING subject_digest, action, window_started_at, attempt_count, blocked_until, updated_at
`

type RecordAuthRateLimitFailureParams struct {
	SubjectDigest []byte `json:"subject_digest"`
	Action        string `json:"action"`
	WindowSeconds int32  `json:"window_seconds"`
	MaxAttempts   int32  `json:"max_attempts"`
	BlockSeconds  int32  `json:"block_seconds"`
}

func (q *Queries) RecordAuthRateLimitFailure(ctx context.Context, arg RecordAuthRateLimitFailureParams) (AuthRateLimit, error) {
	row := q.db.QueryRow(ctx, recordAuthRateLimitFailure,
		arg.SubjectDigest,
		arg.Action,
		arg.WindowSeconds,
		arg.MaxAttempts,
		arg.BlockSeconds,
	)
	var i AuthRateLimit
	err := row.Scan(
		&i.SubjectDigest,
		&i.Action,
		&i.WindowStartedAt,
		&i.AttemptCount,
		&i.BlockedUntil,
		&i.UpdatedAt,
	)
	return i, err
}

